import javax.swing.*;import javax.swing.table.*;import java.awt.*;import java.io.*;
public class CampusEventApp extends JFrame {
 EventService service=new EventService();JTextField sid=new JTextField(8),name=new JTextField(10),email=new JTextField(14);JComboBox<Choice> event=new JComboBox<>(),filter=new JComboBox<>();JLabel status=new JLabel("Ready");DefaultTableModel model=new DefaultTableModel(new String[]{"ID","Student ID","Name","Email","Event","Date"},0);
 record Choice(int id,String name){public String toString(){return name;}}
 CampusEventApp(){super("Campus Event Registration");JMenuBar mb=new JMenuBar();JMenu m=new JMenu("File");JMenuItem ex=new JMenuItem("Export CSV");m.add(ex);mb.add(m);setJMenuBar(mb);JPanel f=new JPanel();f.add(new JLabel("Student ID"));f.add(sid);f.add(new JLabel("Name"));f.add(name);f.add(new JLabel("Email"));f.add(email);f.add(event);JButton reg=new JButton("Register");f.add(reg);JPanel top=new JPanel(new BorderLayout());top.add(f,BorderLayout.NORTH);JPanel fl=new JPanel();fl.add(new JLabel("Filter"));fl.add(filter);JButton refresh=new JButton("Refresh");fl.add(refresh);top.add(fl,BorderLayout.SOUTH);add(top,BorderLayout.NORTH);add(new JScrollPane(new JTable(model)));add(status,BorderLayout.SOUTH);reg.addActionListener(e->register());refresh.addActionListener(e->loadRows());filter.addActionListener(e->loadRows());ex.addActionListener(e->export());setSize(950,450);setDefaultCloseOperation(EXIT_ON_CLOSE);setLocationRelativeTo(null);loadEvents();}
 void loadEvents(){new SwingWorker<java.util.List<String[]>,Void>(){protected java.util.List<String[]> doInBackground()throws Exception{return service.events();}protected void done(){try{for(String[] x:get()){Choice c=new Choice(Integer.parseInt(x[0]),x[1]);event.addItem(c);filter.addItem(c);}filter.addItem("All events");}catch(Exception e){error(e);}}}.execute();}
 Integer filterId(){Object x=filter.getSelectedItem();return x instanceof Choice c?c.id():null;}
 void register(){Choice c=(Choice)event.getSelectedItem();if(c==null)return;String a=sid.getText(),b=name.getText(),d=email.getText();new SwingWorker<Void,Void>(){protected Void doInBackground()throws Exception{service.register(a,b,d,c.id());return null;}protected void done(){try{get();status.setText("Registered");loadRows();}catch(Exception e){error(e);}}}.execute();}
 void loadRows(){new SwingWorker<java.util.List<Object[]>,Void>(){protected java.util.List<Object[]> doInBackground()throws Exception{return service.rows(filterId());}protected void done(){try{model.setRowCount(0);for(Object[] r:get())model.addRow(r);status.setText("Rows: "+model.getRowCount());}catch(Exception e){error(e);}}}.execute();}
 void error(Exception e){Throwable t=e.getCause()==null?e:e.getCause();status.setText(t.getMessage());JOptionPane.showMessageDialog(this,t.getMessage());}
 void export(){JFileChooser c=new JFileChooser();if(c.showSaveDialog(this)!=JFileChooser.APPROVE_OPTION)return;try(PrintWriter w=new PrintWriter(c.getSelectedFile())){for(int j=0;j<model.getColumnCount();j++){if(j>0)w.print(",");w.print(model.getColumnName(j));}w.println();for(int i=0;i<model.getRowCount();i++){for(int j=0;j<model.getColumnCount();j++){if(j>0)w.print(",");w.print(model.getValueAt(i,j));}w.println();}status.setText("CSV exported");}catch(Exception e){error(e);}}
 public static void main(String[] a){SwingUtilities.invokeLater(()->new CampusEventApp().setVisible(true));}
}
